export const UZ={"KUN": ["Yakshanba", "Dushanba", "Seshanba", "Chorshanba", "Payshanba", "Juma", "Shanba"], "OY": ["yanvar", "fevral", "mart", "aprel", "may", "iyun", "iyul", "avgust", "sentabr", "oktabr", "noyabr", "dekabr"], "GREET": ["Assalomu alaykum, onajon 🌷", "Onajon, salomat bo'ling 🌼", "Assalomu alaykum, aziz ona 🌸"], "PRAISE": ["Barakalla! 🌸", "Ofarin, onajon! ✨", "Zo'r! Davom eting 💛", "Mashaalloh! 🌿", "Juda yaxshi! 🌼", "Alloh barakasini bersin 🤲"], "BENEFITS": ["Go'sht va tuxumdagi oqsil mushaklar va bo'y o'sishiga yordam beradi 💪", "Go'sht, mosh va ismaloqdagi temir miya rivojlanishi va diqqat uchun juda muhim 🧠", "Do'stlari bilan bir xil ovqat yeyish unga 'men ham ular kabiman' degan ishonch beradi va yolg'izlik hissini kamaytiradi 🤗", "Uy ovqati kam tuzli, bu uning kichkina buyragi va yuragi uchun foydali ❤️", "Sabzavot va mevadagi tola qorin va ichakni sog'lom saqlaydi 🥕", "Turli ta'mlarni erta tatib ko'rgan bola keyinchalik kamroq injiqlik qiladi 🌈", "Sut va qatiqdagi kalsiy suyak va tishlarni mustahkamlaydi 🦷", "Yumshoq bo'laklarni chaynash nutq mushaklarini rivojlantiradi 🗣", "Baliqdagi omega-3 ko'z va miya uchun foydali 🐟", "Onaning qo'li bilan berilgan taom xotirjamlik beradi, xotirjam bola yaxshi uxlaydi 😴"], "HADITH": [["Har biringiz cho'ponsiz va har biringiz o'z qo'l ostidagilar uchun mas'ulsiz... Ayol erining uyida cho'pondir va o'z qo'l ostidagilar uchun mas'uldir.", "Buxoriy, Muslim"], ["Alloh roziligini istab qilgan har bir sarfingiz uchun ajr olasiz, hatto oilangiz og'ziga solgan luqma uchun ham.", "Buxoriy, Muslim"], ["Oisha (r.a.) aytadilar: bir ayol ikki qizi bilan keldi, unga uchta xurmo berdim. U ikkisiga bittadan berdi, uchinchisini o'zi yemoqchi bo'lganda qizlari so'rashdi va u uni ham ikkiga bo'lib berdi. Rasululloh ﷺ: «Alloh shu sababli unga jannatni vojib qildi» dedilar.", "Muslim"], ["Inson vafot etsa, amali to'xtaydi, faqat uch narsa qoladi: sadaqai joriya, manfaatli ilm va uning haqqiga duo qiladigan solih farzand.", "Muslim"], ["Kichiklarimizga rahm qilmagan bizdan emas.", "Termiziy"], ["Sarflagan dinorlaringiz ichida eng ko'p ajrlisi oilangizga sarflaganingizdir.", "Muslim"], ["«Onang hayotmi?» «Ha.» «Uning yonidan ajrama, chunki jannat uning oyoqlari ostidadir.»", "Nasoiy"], ["Rahm qiluvchilarga Rahmon rahm qiladi. Yerdagilarga rahm qilinglar, osmondagi Zot sizlarga rahm qiladi.", "Abu Dovud, Termiziy"], ["Rasululloh ﷺ nabiralari Hasanni o'pdilar. Bir kishi: «Mening o'nta farzandim bor, birortasini o'pmaganman» dedi. U zot: «Rahm qilmaganga rahm qilinmaydi» dedilar.", "Buxoriy, Muslim"], ["Eng yaxshilaringiz oilasiga yaxshi bo'lganlaringizdir.", "Termiziy"], ["Robbanaa hab lanaa min azvaajinaa va zurriyyaatinaa qurrota a'yun. (Robbimiz, bizga juftlarimiz va zurriyotlarimizdan ko'z quvonchini ato et.)", "Qur'on, Furqon 74"]], "THANKS": ["Barakalla, onajon! 🌸 Bugun o'g'lingizni mehr bilan to'ydirdingiz. Har bir qoshiq sizning sabringiz va muhabbatingizdir.", "Siz ajoyib onasiz! 💐 O'g'lingiz bugun ham do'stlaridan qolishmadi, chunki siz uning yonida bo'ldingiz.", "Charchagan bo'lsangiz ham, bugun hamma narsani qildingiz. Alloh mehnatingizni qabul qilsin! 🤲", "Bugungi kun muvaffaqiyatli yakunlandi! 🎉 Sizning qo'lingizdagi taom uning uchun eng shirin taom."], "AYAH": [["«Yenglar, ichinglar, ammo isrof qilmanglar. Albatta, U isrof qiluvchilarni sevmaydi.»", "A'rof 31"], ["«...Isrofgarchilik bilan sochib yubormang. Albatta, isrofgarlar shaytonlarning birodarlaridir.»", "Isro 26–27"], ["«Ular sarflaganlarida isrof ham, xasislik ham qilmaydilar, balki o'rtacha yo'l tutadilar.»", "Furqon 67"], ["«Qo'lingni bo'yningga bog'lab ham olma, uni butunlay yoyib ham yuborma, aks holda malomatli, hasratli bo'lib qolasan.»", "Isro 29"], ["«...Hosil kunida uning haqqini beringlar va isrof qilmanglar. Albatta, U isrof qiluvchilarni sevmaydi.»", "An'om 141"], ["«Agar shukr qilsangiz, albatta (ne'matimni) ziyoda qilurman.»", "Ibrohim 7"], ["«So'ngra, o'sha kuni ne'matlardan albatta so'ralasizlar.»", "Takosur 8"], ["«Asrga qasamki, albatta inson ziyondadir. Magar imon keltirib, solih amallar qilganlar va bir-birlariga haqni va sabrni tavsiya qilganlar (bundan mustasno).»", "Asr 1–3"], ["«Alloh senga bergan narsa bilan oxirat diyorini istagin va dunyodan nasibangni ham unutmagin.»", "Qasas 77"], ["«Ey imon keltirganlar, Allohdan qo'rqinglar va har bir jon ertaga (oxirat) uchun nima tayyorlaganiga qarasin.»", "Hashr 18"], ["«Sizlarni (yerda) xalifa qilib qo'ygan narsalardan infoq qilinglar.»", "Hadid 7"], ["«Yer isloh qilinganidan keyin unda fasod qilmanglar.»", "A'rof 56"], ["«Osmonni baland qildi va mezonni qo'ydi, toki mezonda haddan oshmanglar.»", "Rahmon 7–8"], ["«Har bir tirik narsani suvdan yaratdik.»", "Anbiyo 30"], ["«Ichadigan suvingizni ko'rdingizmi? Uni bulutdan sizlar tushirdingizmi yoki Biz tushiruvchimizmi?... Shukr qilmaysizlarmi?»", "Voqi'a 68–70"], ["«Ayting: Agar suvingiz yerga singib ketsa, sizlarga kim oqar suv keltira oladi?»", "Mulk 30"], ["«Odamlarning qilmishlari sababli quruqlikda va dengizda fasod paydo bo'ldi.»", "Rum 41"], ["«O'z qo'llaringiz bilan o'zingizni halokatga tashlamanglar va yaxshilik qilinglar.»", "Baqara 195"], ["«Albatta, quloq, ko'z va qalb, bularning har biri haqida so'raladi.»", "Isro 36"], ["«Sizlarni behuda yaratdik deb o'yladingizmi?»", "Mu'minun 115"], ["«Bizning sizlarga rizq qilib bergan pokiza narsalardan yenglar va unda haddan oshmanglar.»", "Toho 81"], ["«Alloh sizlar uchun tirikchilik vositasi qilgan mollaringizni aqli zaif kishilarga bermanglar.»", "Niso 5"]], "HSAVE": [["«Alloh sizlar uchun uch narsani yoqtirmaydi: behuda gap-so'z, ko'p so'rash va molni zoe qilish.»", "Buxoriy, Muslim"], ["«Yenglar, ichinglar, kiyinglar va sadaqa qilinglar, ammo isrof va kibrsiz.»", "Nasoiy, Ibn Moja"], ["Rasululloh ﷺ bir mudd (ikki hovuchcha) suv bilan tahorat, bir so' suv bilan g'usl qilardilar.", "Buxoriy, Muslim"], ["«Luqmangiz tushib ketsa, uni tozalab yenglar, shaytonga qoldirmanglar.»", "Muslim"], ["«Odam bolasi qornidan yomonroq idishni to'ldirmagan. Uning belini tutib turadigan bir necha luqma kifoya.»", "Termiziy"], ["«Ikki kishining taomi uch kishiga, uch kishining taomi to'rt kishiga kifoya qiladi.»", "Buxoriy, Muslim"], ["«Uxlaganingizda uylaringizda olovni yoqilgan holda qoldirmanglar.»", "Buxoriy, Muslim"], ["«Qiyomat kuni banda umrini nimaga o'tkazgani, yoshligini nimaga sarflagani, molini qayerdan topib qayerga sarflagani va ilmiga qanday amal qilgani haqida so'ralmaguncha qadami joyidan jilmaydi.»", "Termiziy"], ["«Musulmonlar uch narsada sherikdirlar: suv, o'tloq va olov.»", "Abu Dovud"], ["«Boylik mol-dunyoning ko'pligi emas, balki boylik ko'ngil boyligidir.»", "Buxoriy, Muslim"], ["«Islomni qabul qilgan, yetarlicha rizq berilgan va Alloh bergan narsaga qanoat qilgan kishi najot topdi.»", "Muslim"], ["«Beshta narsadan oldin beshta narsani g'animat bil: qarilikdan oldin yoshlikni, kasallikdan oldin sog'liqni, kambag'allikdan oldin boylikni, bandlikdan oldin bo'sh vaqtni, o'limdan oldin hayotni.»", "Hokim"], ["«Ikki ne'mat borki, ko'p odamlar ularda aldanadi: sog'liq va bo'sh vaqt.»", "Buxoriy"], ["«Kishi Islomining go'zalligidan biri o'ziga aloqasi yo'q narsani tark etishidir.»", "Termiziy"], ["«Kim Allohga va oxirat kuniga imon keltirsa, yaxshi gapirsin yoki jim tursin.»", "Buxoriy, Muslim"], ["«Kim bir daraxt eksa yoki ekin eksa va undan qush, inson yoki hayvon yesa, bu uning uchun sadaqa bo'ladi.»", "Buxoriy, Muslim"], ["«Agar qiyomat qoyim bo'layotganda birortangizning qo'lida ko'chat bo'lsa, uni eka olsa, eksin.»", "Ahmad, Buxoriy (al-Adab al-mufrad)"], ["«O'zingga foyda beradigan narsaga harakat qil, Allohdan yordam so'ra va ojiz bo'lma.»", "Muslim"], ["«Albatta, badaningning sendan haqqi bor.»", "Buxoriy"], ["«Allohga eng sevimli amal, oz bo'lsa ham, doimiy qilinadiganidir.»", "Buxoriy, Muslim"], ["«Yo'ldan ozor beruvchi narsani olib tashlash sadaqadir.»", "Muslim"]], "SOFT": ["Vaqt, sog'liq, pul, suv, gaz va elektr, hammasi omonat. Tejab ishlataylik 🌿", "Bugun ham ne'matlarni asraylik: vaqtimiz, so'zimiz, kuchimiz va uydagi har bir narsa 🤍", "Oz-oz tejash dunyoda baraka, oxiratda ajr keltiradi 🌱", "Sog'liq va bo'sh vaqt ham ne'mat, ularni ham asraylik 🌸", "Tabiat, suv va daraxtlar bizga omonat. Ehtiyot qilaylik 🌳"], "TIPS_12": ["Do'stlari bilan bir vaqtda ovqatlansa, u o'zini jamoaning bir qismi deb his qiladi 🤝", "Bo'limli likopchaga soling: guruch, sho'rva, asosiy taom, salat, xuddi bog'chadagidek 🍱", "Sho'rvani iliq qilib bering, issiqligini bilagingizga tomizib tekshiring 🌡", "Avval o'zingiz bir qoshiq yeb ko'rsating, bolalar ota-onaga taqlid qiladi 😊", "Bo'laklar no'xatdek mayda bo'lsin, shunda yutish oson va xavfsiz 👌"], "TIPS_16": ["Mevani yuvib, po'stini archib, mayda bo'laklarga bo'ling 🍐", "Tamaddidan oldin birga qo'l yuving, bu ham kichik bir o'yin 🧼", "Suv yoki shakarsiz kompot berishni unutmang 💧", "Tamaddi vaqtida u bilan gaplashing: 'Bu qanday rang? Bu nima?' Nutqi rivojlanadi 🗣"], "RULES": ["Moshni yuvib, kechasi suvga ivitib qo'ying 🫘", "No'xatni kechasi suvga ivitib qo'ying 🫘", "Yasmiqni yuvib, idishga solib qo'ying", "Baliqni muzlatgichdan sovutgichga oling 🐟", "Tovuq go'shtini muzlatgichdan sovutgichga oling 🍗", "Go'shtni muzlatgichdan sovutgichga oling 🥩", "Qiymani tayyorlab, sovutgichda saqlang", "Qiymani tayyorlab, sovutgichda saqlang", "Xamir va qiymani oldindan tayyorlab qo'ying 🥟", "Chuchvarani oldindan tugib, muzlatib qo'ying 🥟", "Sabzini somoncha qilib to'g'rab qo'ying 🥕", "Qovoqni somsa uchun to'g'rab qo'ying 🎃", "Bo'tqa uchun guruch yoki yormani yuvib qo'ying 🍚", "Sut yetarlimi, tekshirib qo'ying 🥛"], "RULE0": "Kerakli sabzavotlarni yuvib, tayyorlab qo'ying 🥬"};
